import{_ as e,o as a,c as r,a6 as d}from"./chunks/framework.BxGSG9WI.js";const p=JSON.parse('{"title":"Scheduled Jobs","description":"The jobs that the TaxJar Integration runs on a schedule: the daily nexus update, the weekly category update, the 15-minute retries and the log cleanup.","frontmatter":{"title":"Scheduled Jobs","description":"The jobs that the TaxJar Integration runs on a schedule: the daily nexus update, the weekly category update, the 15-minute retries and the log cleanup.","type":"reference"},"headers":[],"relativePath":"reference/scheduled-jobs.md","filePath":"reference/scheduled-jobs.md"}'),s={name:"reference/scheduled-jobs.md"};function n(o,t,h,l,i,u){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="scheduled-jobs" tabindex="-1">Scheduled Jobs <a class="header-anchor" href="#scheduled-jobs" aria-label="Permalink to &quot;Scheduled Jobs&quot;">​</a></h1><p>The app runs these jobs on a schedule. You do not start them.</p><table tabindex="0"><thead><tr><th>How Often</th><th>Job</th><th>What It Does</th><th style="text-align:center;">Runs When Off</th></tr></thead><tbody><tr><td><strong>Every 15 Minutes</strong></td><td>Invoice Retry</td><td>Sends failed invoices and cancellations again, when the error is temporary.</td><td style="text-align:center;">-</td></tr><tr><td></td><td>Customer Retry</td><td>Sends failed customers again, when the error is temporary. A customer that waited more than 15 minutes in the queue becomes Failed first.</td><td style="text-align:center;">-</td></tr><tr><td><strong>Daily</strong></td><td>Nexus Update</td><td>Gets the nexus states of each company from TaxJar. On a failure, it sends a notification to the TaxJar users. Refer to <a href="/usa/sales-tax/pr-preview/pr-31/setting-up/updating-your-nexus#daily-update-failure">Daily Update Failure</a>.</td><td style="text-align:center;">-</td></tr><tr><td></td><td>Log Cleanup</td><td>Deletes the TaxJar API Log entries that are older than <strong>Retention</strong>. With 0, it keeps all entries.</td><td style="text-align:center;">●</td></tr><tr><td></td><td>Usage Summary</td><td>Sends a summary of the use of the app, only when usage data is on. Refer to <a href="/usa/sales-tax/pr-preview/pr-31/reference/usage-data-and-feedback">Usage Data &amp; Feedback</a>.</td><td style="text-align:center;">●</td></tr><tr><td><strong>Weekly</strong></td><td>Category Update</td><td>Gets the TaxJar product tax categories, and adds only the new ones.</td><td style="text-align:center;">-</td></tr></tbody></table><p><strong>Runs When Off:</strong> the job also runs when TaxJar is off in <strong>TaxJar Settings</strong>. The other jobs do nothing then.</p><h2 id="retry-rules" tabindex="-1">Retry Rules <a class="header-anchor" href="#retry-rules" aria-label="Permalink to &quot;Retry Rules&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rule</th><th>Value</th></tr></thead><tbody><tr><td>Tries for each document</td><td>Up to 5. After that, send it yourself. Refer to <a href="/usa/sales-tax/pr-preview/pr-31/transaction-sync/resolve-failed-syncs">Resolve Failed Syncs</a>.</td></tr><tr><td>Documents in each run</td><td>50 invoices and 50 customers</td></tr><tr><td>Company with no API token</td><td>The failure does not count as a try. The app sends the document after you add the token.</td></tr><tr><td>Company that no longer syncs</td><td>The app does not retry it.</td></tr></tbody></table>',6)])])}const y=e(s,[["render",n]]);export{p as __pageData,y as default};
